<template><view v-if="show" class="modal-mask" @tap="$emit('cancel')"><view class="modal" @tap.stop><ui-icon v-if="icon" :name="icon" :size="54" :tone="tone"/><text class="title">{{title}}</text><text class="content">{{content}}</text><view class="actions"><view v-if="cancelText" class="secondary" hover-class="tap-active" @tap="$emit('cancel')">{{cancelText}}</view><view class="confirm" hover-class="tap-active" @tap="$emit('confirm')">{{confirmText}}</view></view></view></view></template>
<script>export default{emits:['confirm','cancel'],props:{show:{type:Boolean,default:false},title:{type:String,default:'提示'},content:{type:String,default:''},icon:{type:String,default:''},tone:{type:String,default:'brand'},confirmText:{type:String,default:'确认'},cancelText:{type:String,default:''}}}</script>
<style scoped>.modal-mask{position:fixed;z-index:300;top:0;right:0;bottom:0;left:0;padding:40rpx;display:flex;align-items:center;justify-content:center;background:rgba(7,12,25,.52)}.modal{width:620rpx;padding:42rpx 38rpx 30rpx;display:flex;flex-direction:column;align-items:center;border-radius:28rpx;background:var(--surface);box-shadow:0 28rpx 80rpx rgba(10,20,50,.2)}.title{margin-top:14rpx;font-size:32rpx;font-weight:700}.content{margin-top:20rpx;color:var(--text-secondary);font-size:25rpx;line-height:40rpx;text-align:center}.actions{width:100%;margin-top:36rpx;display:grid;grid-template-columns:repeat(2,1fr);gap:18rpx}.actions>view{height:78rpx;display:flex;align-items:center;justify-content:center;border-radius:40rpx;font-size:27rpx}.actions>.confirm{background:var(--primary);color:#fff}.actions>.secondary{background:var(--surface-soft);color:var(--text)}.actions>view:only-child{grid-column:1/3}</style>
